const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=node=>node?.labels?.['zh-hans']||node?.labels?.zh||node?.labels?.en||node?.id||'来源名称未知';
export function mountTaxonomy(container,{onGenre=()=>{}}={}){
 let graph={genres:[],nodes:[]},records=[],selected='Q24925',search='';
 let nodes=new Map(),counts=new Map(),children=new Map(),sourceLabels=new Map(),trail=[];
 container.innerHTML=`<div class="section-heading"><div><span class="eyebrow">BRANCHES / SOURCE ONTOLOGY</span><h2>展开分支的细枝末节</h2></div><p>来源中的原始标签与父子关系，一并保留。</p></div><p class="section-intro">这是 Wikidata 来源分类的关系图，包含体裁、题材与更泛的类别。来源标签并不等同底层议题，也不自动证明作品身份。记录数按全站当前筛选与直接 genre 声明计，不累加父类或把多标签计作多部作品。</p><div class="taxonomy-summary" aria-live="polite">正在载入分类谱系…</div><div class="taxonomy-layout"><aside><label>搜索分支与来源编号<input type="search" class="taxonomy-search" placeholder="太空歌剧、cyberpunk、Q24925…"></label><p class="taxonomy-list-status"></p><div class="taxonomy-index"></div></aside><div class="taxonomy-graph"><div class="taxonomy-trail"></div><div class="taxonomy-neighborhood"></div><p class="taxonomy-note">箭头表示来源 P279「是其子类」的方向。每次展开当前节点及其直接相邻节点；完整节点、所有祖先与全部边均可下载核对。</p><a href="./assets/genre-hierarchy.json" download>下载完整分支谱系 JSON ↗</a></div></div>`;
 const find=selector=>container.querySelector(selector);
 function card(id){const node=nodes.get(id)||{id};return `<button class="taxonomy-node" data-node="${escape(id)}"><strong>${escape(name(node))}</strong><small>${escape(id)} · ${counts.get(id)||0} 条直接记录</small></button>`;}
 function renderIndex(){const query=search.toLocaleLowerCase();const list=graph.genres.filter(g=>[g.id,...Object.values(g.labels||{})].join(' ').toLocaleLowerCase().includes(query)).sort((a,b)=>(counts.get(b.id)||0)-(counts.get(a.id)||0)||name(a).localeCompare(name(b),'zh-CN'));find('.taxonomy-list-status').textContent=`${list.length} / ${graph.genres.length} 个原始标签`;find('.taxonomy-index').innerHTML=list.length?list.map(g=>card(g.id)).join(''):'没有匹配的来源标签。';}
 function renderGraph(){const node=nodes.get(selected)||{id:selected,parents:[]};find('.taxonomy-trail').innerHTML=trail.map(id=>`<button data-node="${escape(id)}">${escape(name(nodes.get(id)||{id}))}</button>`).join('<span aria-hidden="true"> → </span>');find('.taxonomy-neighborhood').innerHTML=`<div class="taxonomy-column"><h3>更细的直接子类</h3>${(children.get(selected)||[]).map(card).join('')||'<p>本次来源图未记有直接子类。</p>'}</div><div class="taxonomy-current"><span>当前节点</span><h3>${escape(name(node))}</h3><small>${escape(selected)}</small><strong>${counts.get(selected)||0}<small>条直接声明该标签的书目</small></strong>${counts.has(selected)?'<button class="button" data-open-genre>浏览该分支书目 →</button>':''}<a href="https://www.wikidata.org/wiki/${escape(selected)}" target="_blank" rel="noopener noreferrer">查看来源节点 ↗</a></div><div class="taxonomy-column"><h3>是其子类 → 直接父类</h3>${(node.parents||[]).map(card).join('')||'<p>本次来源图未记有直接父类。</p>'}</div>`;}
 function select(id){if(!nodes.has(id))return;selected=id;if(trail.at(-1)!==id)trail=[...trail.slice(-5),id];renderGraph();}
 const click=e=>{const target=e.target.closest('button');if(target?.dataset.node)select(target.dataset.node);if(target?.hasAttribute('data-open-genre'))onGenre(sourceLabels.get(selected)||name(nodes.get(selected)));};
 const input=e=>{search=e.target.value;renderIndex();};container.addEventListener('click',click);find('.taxonomy-search').addEventListener('input',input);
 return {update(data,items=[]){graph=data;records=items;nodes=new Map(graph.nodes.map(n=>[n.id,n]));for(const genre of graph.genres)if(!nodes.has(genre.id))nodes.set(genre.id,genre);counts=new Map();sourceLabels=new Map();children=new Map();for(const node of nodes.values())for(const parent of node.parents||[]){if(!children.has(parent))children.set(parent,[]);children.get(parent).push(node.id);}for(const record of records)for(const genre of record.source_subject||[]){counts.set(genre.id,(counts.get(genre.id)||0)+1);sourceLabels.set(genre.id,genre.label);}find('.taxonomy-summary').textContent=`${graph.genres.length} 个作品原始分支标签（计数随全站筛选） · ${graph.nodes.length} 个层级节点 · ${graph.nodes.reduce((sum,n)=>sum+(n.parents||[]).length,0)} 条父子关系`;if(!nodes.has(selected))selected=graph.genres[0]?.id;trail=[selected];renderIndex();renderGraph();},destroy(){container.removeEventListener('click',click);find('.taxonomy-search').removeEventListener('input',input);container.replaceChildren();}};
}
